        choice(t(ctx,'Diseños predeterminados','Default designs'),[['auto',t(ctx,'Según el tema','Match theme')],['modern',t(ctx,'Moderno','Modern')],['cute','Cute'],['minimal','Minimal'],['natural','Natural'],['geek','Geek']],'artStyle');
