function getWorkspaceStarterLayout(template = "desk") {
  if (template === "room") return [{ id: createEntityId("room"), type: "cozy_room", column: "center", height: 600, gridX: 0, gridY: 0, gridW: 12, gridH: 25 }];
  return [
    { id: "panel-notebooks", type: "notebooks", column: "center", height: 560, gridX: 0, gridY: 0, gridW: 8, gridH: 24 },
    { id: "panel-recent", type: "recent", column: "right", height: 280, gridX: 8, gridY: 0, gridW: 4, gridH: 12 },
    { id: "panel-tasks", type: "tasks", column: "right", height: 280, gridX: 8, gridY: 12, gridW: 4, gridH: 12 },
    { id: "panel-draft", type: "quick_note_draft", column: "center", height: 264, gridX: 0, gridY: 24, gridW: 12, gridH: 11 },
  ].map(panel => ({ ...panel }));
}
function searchWorkspaceNotes(files, query) {
  const fold = value => String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase();
  const term = fold(query.trim());
  if (!term) return [];
  return files.filter(file => file.extension === "md" && !file.path.split("/").some(part => part.startsWith(".")) && fold(file.path).includes(term))
    .sort((a, b) => Number(fold(b.basename).startsWith(term)) - Number(fold(a.basename).startsWith(term)) || String(a.path).localeCompare(String(b.path)))
    .slice(0, 8);
}
