function isCozyWallObject(type) {
  if(type==="clay_photo_garland")return true;
  if(type.startsWith("kawaii_")&&/_(frame|poster)$/.test(type))return true;
  return type === "painting" || type === "wall_calendar" || type === "wall_clock" || type === "painting_city" || type === "painting_space" || type === "painting_abstract" || type.startsWith("poster_taylor_") || type === "corkboard";
}

