function getCozyFurnitureAtlasUrls(style="classic",asset=name=>name) {
  const base={classic:"cozy-furniture-v1.png",office:"cozy-office-v2.png",home:"cozy-home-v2.png",decor:"cozy-decor-v2.png","turns-study":"cozy-turns-study-v1.png","turns-home":"cozy-turns-home-v1.png"};
  if(style!=="classic") for(const key of Object.keys(base)) base[key]=`furniture-${style}-${key}-v1.png`;
  for(const key of ["extras-games","extras-decor","extras-tech","personal-plush","personal-study","personal-hobbies","personal-cat","personal-desks","personal-buttons"]) base[key]=`furniture-${style}-${key}-v1.png`;
  base['switch-poses']=`furniture-${style}-switch-poses-v1.png`;
  base['pet-dog']=style==='clay'?'pet-dog-clay/frame-00.png':'pet-dog/frame-00.png';
  for(const key of ["kawaii-animals","kawaii-wall-soft","kawaii-decor"])base[key]=style==="clay"?`furniture-clay-${key}-v1.png`:`cozynity-${key}-v1.png`;
  COZY_ROOM_FURNITURE.filter(item=>item.collection==="clay").forEach(item=>{base[item.atlas]=`cozynity-${item.atlas}-v1.png`;});
  return Object.fromEntries(Object.entries(base).map(([key,file])=>[key,asset(file)]));
}

function snapCozyPosition(x, y, minY=0) {
  // Subdivide the existing coordinates; keep saved positions and room bounds.
  const coord = (n,max,min=0) => clamp(Math.round((Number.isFinite(Number(n)) ? Number(n) : 0)*4)/4,min,max);
  return {x:coord(x,20),y:coord(y,12,minY)};
}

function normalizeCozyObjectScale(value) {
  return Number.isFinite(Number(value)) ? clamp(Number(value),0.25,3) : 1;
}

