  [["all","Todo","All"],["furniture","Muebles","Furniture"],["study","Trabajo y estudio","Work & study"],["kitchen","Cocina","Kitchen"],["lighting","Iluminación","Lighting"],["decor","Decoración","Decor"],["kawaii","Kawaii · pastel","Kawaii · pastel"],["clay","Cozy Clay · cerámica","Cozy Clay · ceramics"]].forEach(([value,es,en])=>category.createEl("option",{text:t(es,en),attr:{value}}));
