    const close=doc.createElement("button");close.type="button";close.className="cozy-nest-room-palette-close";close.setAttribute("aria-label",t("Cerrar","Close"));close.textContent="×";
    header.append(move,fold,close);paletteRoot.append(header);
    const tabs=doc.createElement("div");tabs.className="cozy-nest-room-palette-tabs";tabs.setAttribute("role","tablist");
    const tab=(id,label)=>{const el=doc.createElement("button");el.type="button";el.className="cozy-nest-room-palette-tab";el.setAttribute("role","tab");el.setAttribute("aria-controls",paletteId+"-"+id);el.dataset.paletteTab=id;el.textContent=label;tabs.append(el);return el;};
    const furnitureTab=tab("furniture",t("Muebles","Furniture")),ambienceTab=tab("ambience",t("Ambiente","Ambience"));paletteRoot.append(tabs);
    const bodyEl=doc.createElement("div");bodyEl.className="cozy-nest-room-palette-body";
    const furniturePanel=doc.createElement("div");furniturePanel.className="cozy-nest-room-palette-tabpanel";furniturePanel.id="cozy-nest-room-palette-tabpanel-furniture";furniturePanel.setAttribute("role","tabpanel");furniturePanel.setAttribute("aria-label",t("Muebles","Furniture"));
    const ambiencePanel=doc.createElement("div");ambiencePanel.className="cozy-nest-room-palette-tabpanel";ambiencePanel.id="cozy-nest-room-palette-tabpanel-ambience";ambiencePanel.setAttribute("role","tabpanel");ambiencePanel.setAttribute("aria-label",t("Ambiente","Ambience"));
    furniturePanel.id=paletteId+"-furniture";ambiencePanel.id=paletteId+"-ambience";
    bodyEl.append(furniturePanel,ambiencePanel);paletteRoot.append(bodyEl);body.append(paletteRoot);
    const lightingLabel=doc.createElement("label");lightingLabel.className="cozy-nest-room-palette-lighting";lightingLabel.textContent=t("Iluminación","Lighting");
    const lighting=doc.createElement("select");lighting.className="cozy-nest-room-lighting";lighting.setAttribute("aria-label",t("Iluminación","Lighting"));
    [["honey","Día","Day"],["forest","Suave","Soft"],["night","Noche","Night"]].forEach(([value,es,en])=>{const option=doc.createElement("option");option.value=value;option.textContent=t(es,en);lighting.append(option);});
    lighting.addEventListener("change",()=>{if(!roomIsAlive())return;room.palette=lighting.value;void persist();});lightingLabel.append(lighting);ambiencePanel.append(lightingLabel,roomActions,finishes);
    furniturePanel.append(inspector,filters,catalog);
    const hint=doc.createElement("p");hint.className="cozy-nest-room-palette-help";hint.textContent=t("Arrastrá los muebles a la grilla. Flechas: ajuste fino; Shift: cuatro pasos.","Drag furniture onto the grid. Arrows: fine adjustment; Shift: four steps.");furniturePanel.prepend(hint);
    const setTab=id=>{paletteTab=id;const active=id==="ambience"?ambienceTab:furnitureTab;[furnitureTab,ambienceTab].forEach(tabEl=>{const on=tabEl===active;tabEl.setAttribute("aria-selected",String(on));tabEl.tabIndex=on?0:-1;});furniturePanel.hidden=id!=="furniture";ambiencePanel.hidden=id!=="ambience";};
    furnitureTab.addEventListener("click",()=>setTab("furniture"));ambienceTab.addEventListener("click",()=>setTab("ambience"));setTab(paletteTab);
    tabs.addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(e.key))return;e.preventDefault();setTab(e.key==="Home"?"furniture":e.key==="End"?"ambience":paletteTab==="furniture"?"ambience":"furniture");(paletteTab==="furniture"?furnitureTab:ambienceTab).focus();});
    const clampPosition=(left,top)=>{const width=paletteRoot.getBoundingClientRect().width||320,height=paletteRoot.getBoundingClientRect().height||260,maxX=Math.max(8,(doc.documentElement.clientWidth||window.innerWidth)-width-8),maxY=Math.max(8,(doc.documentElement.clientHeight||window.innerHeight)-height-8);return [clamp(left,8,maxX),clamp(top,8,maxY)];};
    const setPosition=(left,top)=>{const [x,y]=clampPosition(left,top);paletteRoot.style.left=x+"px";paletteRoot.style.top=y+"px";};
    const sceneBox=scene.getBoundingClientRect(),viewportWidth=doc.documentElement.clientWidth||window.innerWidth,viewportHeight=doc.documentElement.clientHeight||window.innerHeight,paletteWidth=Math.min(320,Math.max(220,viewportWidth-24));
    let left=sceneBox.right+12;if(left+paletteWidth>viewportWidth-8)left=viewportWidth-paletteWidth-8;setPosition(left,Math.max(8,Math.min(sceneBox.top,viewportHeight-280)));
